	{
		eventCounter++;
		CMND_BTL_DISABLE_RETURN_MENU("KsnBtlMenu");
		CMND_BTL_SET_EVPARAM(44010110);
		suspend();
		CMND_SET_GLOBAL_BIT_FLAG(1402, 1);
		CMND_BTL_STOP_AI(0);
		CMND_BTL_SET_PURPOSE(1, 9, true, 0, 10);
		CMND_BTL_SET_PURPOSETEXT(true, "purpose_120", "para_cp0009");
		// para_cp0009's Fighting Spirit cannot run out
		CMND_BTL_SET_KESHIN_INVINCIBLE(true, "para_cp0009");
	}
};
